promql:
sum(
  machine_cpu_sockets{node="k8s-node3"} or
  machine_cpu_sockets{node="k8s-node4"} or
  machine_cpu_sockets{node="k8s-node5"}
)

let current_orphans = node_sockstat_TCP_orphan{instance="10.176.122.152:9100"}
let orphans_one_week_ago = node_sockstat_TCP_orphan{instance="10.176.122.152:9100"} offset 1w
{
  "current_orphans": current_orphans,
  "ratio_to_last_week": current_orphans / orphans_one_week_ago
}

topk(1,
  label_replace(
    sum by (span_name) (
      rate(traces_spanmetrics_latency_sum{service="ts-user-service"}[5m])
    ) 
    / 
    sum by (span_name) (
      rate(traces_spanmetrics_latency_count{service="ts-user-service"}[5m])
    ),
    "api", "$1", "span_name", "(.*)"
  )
)

{
  api_generate: histogram_quantile(0.99, sum(rate(traces_spanmetrics_latency_bucket{service="ts-verification-code-service", span_name="GET /api/v1/verifycode/generate"}[5m])) by (le)),
  api_verify: histogram_quantile(0.99, sum(rate(traces_spanmetrics_latency_bucket{service="ts-verification-code-service", span_name="GET /api/v1/verifycode/verify/{verifyCode}"}[5m])) by (le))
}
